L000047	\section{Derivation of Eq. (15)}
L000048	We focus on the first order term of Eq. (15). Inserting Eqs. (13) and (14) in $\langle \Psi_\lambda (\mathbf{q})|e^{i\mathbf{q \cdot r}}|\Psi_\mu \rangle $ and writing $A_{cv\mathbf{k}}^\lambda (\mathbf{q})$ as $A_{c\mathbf{k+q}, v\mathbf{k}}^\lambda$, leads to
L000049	\begin{equation}
L000050	    \sum_{cv\mathbf{k}}(A_{c\mathbf{k+q},v\mathbf{k}}^{\lambda })^* \sum_{c'v'\mathbf{k}'} A_{c'\mathbf{k}',v'\mathbf{k'}}^{\mu} \sum_{nn'\mathbf{k''}} \langle u_{n\mathbf{k''+q}}|u_{n'\mathbf{k''}} \rangle \langle 0| c_{v\mathbf{k}}^\dagger c_{c\mathbf{k+q}} c_{n\mathbf{k'' + q}}^\dagger c_{n' \mathbf{k''}} c_{c'\mathbf{k}'}^\dagger c_{v'\mathbf{k}'} |0 \rangle ,
L000051	\end{equation}
L000052	where the operator product can be simplified with Wick's theorem
L000053	\begin{equation}
L000054	    \begin{split}
L000055	    c_{v\mathbf{k}}^\dagger c_{c\mathbf{k+q}} c_{n\mathbf{k'' + q}}^\dagger c_{n' \mathbf{k''}} c_{c'\mathbf{k}'}^\dagger c_{v'\mathbf{k}'} &= \, \bcancel{ :c_{v\mathbf{k}}^\dagger c_{c\mathbf{k+q}} c_{n\mathbf{k'' + q}}^\dagger c_{n' \mathbf{k''}} c_{c'\mathbf{k}'}^\dagger c_{v'\mathbf{k}'}: }
L000056	    + \, \bcancel{\delta_{cn}\delta_{\mathbf{kk''}}:c_{v\mathbf{k}}^\dagger c_{n' \mathbf{k''}} c_{c'\mathbf{k}'}^\dagger c_{v'\mathbf{k}'}:} \\
L000057	    &+ \bcancel{\delta_{n'c'}\delta_{\mathbf{k''k'}}:c_{v\mathbf{k}}^\dagger c_{c\mathbf{k+q}} c_{n\mathbf{k'' + q}}^\dagger c_{v'\mathbf{k}'}:}
L000058	    + \, \delta_{cc'}\delta_{\mathbf{k+q,k'}}:c_{v\mathbf{k}}^\dagger c_{n\mathbf{k'' + q}}^\dagger c_{n' \mathbf{k''}}  c_{v'\mathbf{k}'}: \\
L000059	    &+ \delta_{cn}\delta_{\mathbf{kk''}}\delta_{n'c'}\delta_{\mathbf{k''k'}}:c_{v\mathbf{k}}^\dagger  c_{v'\mathbf{k}'}: \, \\
L000060	    &= -\delta_{cc'}\delta_{\mathbf{k+q,k'}}\delta_{vn'}\delta_{\mathbf{kk''}}\delta_{nv'} + \, \delta_{cn}\delta_{\mathbf{kk''}}\delta_{n'c'}\delta_{\mathbf{k'',k'}}\delta_{vv'} \, .
L000061	\end{split}
L000062	\end{equation}
L000063	Inserting Eq. (S2) in Eq. (S1), we have
L000064	\begin{equation}
L000065	    -\sum_{cvv'\mathbf{k'}} (A_{c\mathbf{k'},v\mathbf{k'-q}}^\lambda)^* A_{c\mathbf{k'},v'\mathbf{k'}}^\mu \langle u_{v'\mathbf{k'}} | u_{v\mathbf{k'-q}} \rangle + \sum_{cc'v\mathbf{k}} (A_{c\mathbf{k+q},v\mathbf{k}}^\lambda)^* A_{c'\mathbf{k},v\mathbf{k}}^\mu \langle u_{c\mathbf{k+q}} | u_{c'\mathbf{k}} \rangle .
L000066	\end{equation}
L000067	Now, we expand Eq. (S3) to first order of $\mathbf{q}$. Firstly, expand the Bloch overlap terms (changing dummy index $\mathbf{k}'$ to $\mathbf{k}$)
L000068	\begin{equation}
L000069	    \begin{split}
L000070	        \langle u_{v'\mathbf{k}} | u_{v\mathbf{k-q}} \rangle &= - \mathbf{q} \cdot \langle u_{v'\mathbf{k}} | \partial_{\mathbf{k}} u_{v\mathbf{k}} \rangle = i\mathbf{q} \cdot \bm{\mathcal{A}}_{v'v\mathbf{k}} \, , \\
L000071	        \langle u_{c\mathbf{k+q}} | u_{c'\mathbf{k}} \rangle &=  \mathbf{q} \cdot \langle \partial_{\mathbf{k}} u_{c\mathbf{k}} | u_{c'\mathbf{k}} \rangle = i\mathbf{q} \cdot \bm{\mathcal{A}}_{cc'\mathbf{k}} \, .
L000072	    \end{split}
L000073	\end{equation}
L000074	Including zeroth-order exciton envelopes in Eq. (S4), yields
L000075	\begin{equation}
L000076	    i\mathbf{q} \cdot \left[ \sum_{cc'v\mathbf{k}} (A_{cv\mathbf{k}}^\lambda)^* A_{c'v\mathbf{k}}^\mu \bm{\mathcal{A}}_{cc'\mathbf{k}} - \sum_{cvv'\mathbf{k}} (A_{cv\mathbf{k}}^\lambda)^* A_{cv'\mathbf{k}}^\mu \bm{\mathcal{A}}_{v'v\mathbf{k}} \right] \, .
L000077	\end{equation}
L000078	If we take zeroth-order of the Bloch overlaps, Eq. (S3) survives only for $v'=v$ and $c=c'$, and becomes
L000079	\begin{equation}
L000080	    \sum_{cv\mathbf{k}} \left[ (A_{c\mathbf{k+q},v\mathbf{k}}^\lambda)^* - (A_{c\mathbf{k},v\mathbf{k-q}}^\lambda)^*\right] A_{c\mathbf{k},v\mathbf{k}}^\mu  = \mathbf{q} \cdot \sum_{cv\mathbf{k}} \partial_\mathbf{k} (A_{c\mathbf{k},v\mathbf{k}}^\lambda)^* A_{c\mathbf{k},v\mathbf{k}}^\mu \\
L000081	     = i\mathbf{q} \cdot \sum_{cv\mathbf{k}} (A_{cv\mathbf{k}}^\lambda)^\ast i\partial_\mathbf{k} A_{cv\mathbf{k}}^\mu \, .
L000082	\end{equation}
L000083	We see that Eqs. (S5) and (S6) (removing prefactor $i\mathbf{q}$) are exactly the same as Eqs. (16) and (17) with different grouping of terms.
L000084	
L000085	\section{Derivation of inter-exciton transition dipole moment}
L000086	To evaluate $\bm{\mathcal{R}}_{\lambda \mu} = \langle \Psi_\lambda |\mathbf{r}|\Psi_\mu \rangle$, we use
L000087	\begin{equation}
L000088	    |\Psi_\lambda \rangle = \sum_{cv\mathbf{k}} A_{cv\mathbf{k}}^\lambda c_{c\mathbf{k}}^\dagger c_{v\mathbf{k}} |0\rangle , \quad |\Psi_\mu \rangle = \sum_{c'v'\mathbf{k}'} A_{c'v'\mathbf{k}'}^\lambda c_{c'\mathbf{k}'}^\dagger c_{v'\mathbf{k}'} |0\rangle ,
L000089	\end{equation}
L000090	and the position operator
L000091	\begin{equation}
L000092	    \mathbf{r} = \sum_{nm\mathbf{k}'' \mathbf{k}'''} \langle u_{n\mathbf{k}''} |\mathbf{r} | u_{m\mathbf{k}'''} \rangle c_{n\mathbf{k}''}^\dagger c_{m\mathbf{k}'''}.
L000093	\end{equation}
L000094	Note that the matrix elements of the position operator should be understood as
L000095	\begin{equation}
L000096	    \mathbf{r}_{nm\mathbf{k}'' \mathbf{k}'''} = (1-\delta_{nm})\delta_{\mathbf{k}'' \mathbf{k}'''} \bm{\mathcal{A}}_{nm\mathbf{k}''} + \delta_{nm}(\delta_{\mathbf{k}'' \mathbf{k}'''} \bm{\mathcal{A}_{nn\mathbf{k}''}} + i\bm{\nabla}_{\mathbf{k}''} \delta_{\mathbf{k}'' \mathbf{k}'''}) \, ,
L000097	\end{equation}
L000098	where the first and second terms correspond to the \emph{interband} and \emph{intraband} contributions, respectively. Inserting Eqs. (S7) and (S8), we have
L000099	\begin{equation}
L000100	    \bm{\mathcal{R}}_{\lambda \mu} = \langle 0 |\sum_{cv\mathbf{k}} (A_{cv\mathbf{k}}^{\lambda})^\ast c_{v\mathbf{k}}^\dagger c_{c\mathbf{k}} \sum_{nm\mathbf{k'' k'''}} \mathbf{r}_{nm\mathbf{k'' k'''}} c_{n\mathbf{k''}}^\dagger c_{m\mathbf{k'''}} \sum_{c' v' \mathbf{k}'} A_{c' v' \mathbf{k}'}^\mu c_{c' \mathbf{k}'}^\dagger c_{v' \mathbf{k}'} |0\rangle,
L000101	\end{equation}
L000102	where the operator product can be simplified with Wick's theorem
L000103	\begin{equation}
L000104	    \begin{split}
L000105	        c_{v\mathbf{k}}^\dagger c_{c\mathbf{k}} c_{n\mathbf{k}''}^\dagger c_{m\mathbf{k}'''} c_{c' \mathbf{k}'}^\dagger c_{v' \mathbf{k}'} =& \bcancel{\mathord{:} c_{v\mathbf{k}}^\dagger c_{c\mathbf{k}} c_{n\mathbf{k}''}^\dagger c_{m\mathbf{k}'''} c_{c' \mathbf{k}'}^\dagger c_{v' \mathbf{k}'} \mathord{:} }
L000106	        + \bcancel{\delta_{cn} \delta_{\mathbf{kk''}} \mathord{:} c_{v\mathbf{k}}^\dagger  c_{m\mathbf{k}'''} c_{c' \mathbf{k}'}^\dagger c_{v' \mathbf{k}'} \mathord{:}} \\
L000107	        +& \bcancel{\delta_{mc'} \delta_{\mathbf{k''' k'}} \mathord{:} c_{v\mathbf{k}}^\dagger c_{c\mathbf{k}} c_{n\mathbf{k''}}^\dagger  c_{v' \mathbf{k}'} \mathord{:} }
L000108	        + \delta_{cc'} \delta_{\mathbf{kk}'} \mathord{:} c_{v\mathbf{k}}^\dagger c_{n\mathbf{k''}}^\dagger c_{m\mathbf{k'''}} c_{v' \mathbf{k}'} \mathord{:} \\
L000109	        +& \delta_{cn} \delta_{\mathbf{kk''}} \delta_{mc'} \delta_{\mathbf{k''' k'}} \mathord{:} c_{v\mathbf{k}}^\dagger  c_{v' \mathbf{k}'} \mathord{:}
L000110	    \end{split}
L000111	\end{equation}
L000112	The last term can be nonzero only when $v = v'$ and $\mathbf{k} = \mathbf{k'}$. Inserting this term in Eq. (S10), we have the interband contribution
L000113	\begin{equation}
L000114	    \sum_{cv\mathbf{k}} \sum_{c' v' \mathbf{k}'} \sum_{nm \mathbf{k''k'''}} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c' v' \mathbf{k} '}^\mu \mathbf{r}_{nm\mathbf{k''k'''}} \delta_{cn} \delta_{\mathbf{kk''}} \delta_{mc'} \delta_{\mathbf{k'''k'}} \delta_{vv'} \delta_{\mathbf{kk}'}
L000115	    = \sum_{cv\mathbf{k}, c' \neq c} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c' v \mathbf{k}}^\mu \bm{\mathcal{A}}_{cc' \mathbf{k}} \, .
L000116	\end{equation}
L000117	For the intraband part, we should evaluate the derivative before assigning $\mathbf{k}=\mathbf{k}'$, yielding
L000118	\begin{equation}
L000119	    \sum_{cv\mathbf{k}} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c v \mathbf{k}}^\mu \bm{\mathcal{A}}_{cc\mathbf{k}} + i (A_{cv\mathbf{k}}^{\lambda})^\ast \partial_\mathbf{k} A_{c v \mathbf{k}}^\mu \, .
L000120	\end{equation}
L000121	There are two possible manipulations for the second to last term of Eq. (S11) to be nonzero: $D1 = \delta_{cc'} \delta_{\mathbf{kk}'} \delta_{nm} \delta_{\mathbf{k''k'''}} \delta_{vv'}$ and $D2 = -\delta_{cc'} \delta_{\mathbf{kk}'} \delta_{nv'} \delta_{\mathbf{k''k'}} \delta_{vm} \delta_{\mathbf{kk'''}}$. Inserting D1 in Eq. (S10), we have
L000122	\begin{equation}
L000123	    \sum_{cv\mathbf{k}} \sum_{c' v' \mathbf{k}'}  (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c' v' \mathbf{k} '}^\mu \delta_{cc'} \delta_{vv'} \delta_{\mathbf{kk}'} \sum_{nm \mathbf{k''k'''}} \mathbf{r}_{nm\mathbf{k''k'''}} \delta_{nm} \delta_{\mathbf{k''k'''}} = 0,
L000124	\end{equation}
L000125	thanks to the orthogonality $\sum_{cv\mathbf{k}} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{cv\mathbf{k}}^\mu =0 $. Inserting D2 in Eq. (S10), we obtain
L000126	\begin{equation}
L000127	    -\sum_{cv\mathbf{k}, v' \neq v} (A_{cv\mathbf{k}}^{\lambda})^\ast  A_{cv' \mathbf{k}}^\mu \bm{\mathcal{A}}_{v' v \mathbf{k}} \, ,
L000128	\end{equation}
L000129	for the interband contribution, and the intraband component
L000130	\begin{equation}
L000131	    -\sum_{cv\mathbf{k}} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c v \mathbf{k}}^\mu\bm{\mathcal{A}}_{vv\mathbf{k}} + \bcancel{i [(A_{cv\mathbf{k}}^{\lambda})^\ast \partial_\mathbf{k} A_{c v \mathbf{k}}^\mu + \partial_\mathbf{k} (A_{cv\mathbf{k}}^{\lambda})^\ast A_{c v \mathbf{k}}^\mu]} .
L000132	\end{equation}
L000133	Combining Eqs. (S12--S13) and (S15--S16), we arrive at the Eqs. (16) and (17) of $\bm{\mathcal{R}}_{\lambda \mu}$.
L000134	
L000135	
L000136	\section{convergence}
