L000179	\title{\textit{Ab initio} \textit{GW}-BSE theory of optical activity in $\alpha$-quartz}
L000180	
L000181	
L000182	\author{Xiaoming Wang}
L000183	\email{xiaoming.wang@utoledo.edu}
